<template>
  <div id="app_data">
    <h1>App Data<span class="note">（需要快应用引擎>1040）</span></h1>
    <p>暂不支持包含中文的修改</p>
    <label for="checkbox">暂不能检测Page内数据变动，是否打开自动刷新: {{ checked }}</label>
    <input type="checkbox" id="checkbox" @click="autoRefresh" v-model="checked">
    <div v-for="item in pages" :key="item.pageId">
      <h3>
        pageId: {{ item.pageId }}, name: {{ item.name }}, path: {{item.path}}
      </h3>
      <div :ref="'pageId'+item.pageId"></div>
    </div>
  </div>
</template>

<script>
import JSONEditor from 'jsoneditor'
import { debounce, getDiffJson } from '../util'
import 'jsoneditor/dist/jsoneditor.min.css'

let editorInstances = Object.create(null)

export default {
  data () {
    return {
      checked: false,
      framework: '',
      checkEvent: undefined,
      toolkit: ''
    }
  },
  computed: {
    pages () {
      return this.$store.state.pages
    }
  },
  methods: {
    autoRefresh (e) {
      if (e.target.checked) {
        this.checkEvent = setInterval(() => {
          this.$store.dispatch('getPageData')
        }, 5000)
      } else {
        if (this.checkEvent) {
          clearInterval(this.checkEvent)
          this.checkEvent = undefined
        }
      }
    },
    change (pageId) {
      const editor = editorInstances[pageId]
      const updatedJson = editor.get()
      // 尝试对比得出两个 json 差异的地方，效果不好则去掉改为全量覆盖
      const diffJson = getDiffJson(editor.originData, updatedJson)
      editor.originData = updatedJson
      this.$store.dispatch('updateData', {
        pageId,
        data: diffJson
      })
    },
    getEditorOption (pageId) {
      return {
        enableTransform: false,
        enableSort: false,
        limitDragging: false,
        sortObjectKeys: false,
        navigationBar: false,
        language: 'en',
        mode: 'tree',
        modes: ['tree', 'code'],
        onChange: debounce(this.change.bind(this, pageId), 500)
      }
    },
    destroyEditors () {
      for (const ref in editorInstances) {
        editorInstances[ref].destroy()
      }
      editorInstances = Object.create(null)
    },
    initEditor () {
      // 先清空
      this.destroyEditors()
      for (const page of this.pages) {
        const pageId = page.pageId
        const options = this.getEditorOption(pageId)
        const ref = 'pageId' + pageId
        const editor = new JSONEditor(this.$refs[ref][0], options, page.data)
        editor.originData = page.data
        editorInstances[pageId] = editor
      }
    }
  },
  created () {
    this.$store.dispatch('getPageData')
  },
  updated () {
    this.initEditor()
  }
}
</script>

<style lang="stylus">

#app_data {
  padding: 30px;
}

</style>
