// 防抖
export function debounce (func, wait) {
  let timer
  return () => {
    const args = arguments
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => {
      func.apply(this, args)
    }, wait)
  }
}

/**
 * 得出两个json不同的地方
 * @param {Object} src - 旧json
 * @param {Object} dest - 新json
 * @return {Object} diff - 差异的json
 */
// value为对象则递归检查，为数组则直接转为字符串判断
export function getDiffJson (src, dest) {
  const diff = Object.create(null)

  function compare (_src, _dest, _diff) {
    let result
    Object.keys(_src).forEach((attr) => {
      let flag = false
      if (_dest[attr]) {
        if (_dest[attr].constructor.name === 'Object') {
          _diff[attr] = Object.create(null)
          if (compare(_src[attr], _dest[attr], _diff[attr])) {
            flag = true
          }
        } else if (_dest[attr].constructor.name === 'Array') {
          if (JSON.stringify(_dest[attr]) !== JSON.stringify(_src[attr])) {
            _diff[attr] = _dest[attr]
            flag = true
          }
        } else {
          if (_dest[attr] !== _src[attr]) {
            _diff[attr] = _dest[attr]
            flag = true
          }
        }
        if (flag) {
          result = flag
        } else {
          delete _diff[attr]
        }
      }
    })
    return result
  }
  compare(src, dest, diff)

  return diff
}
